 switch(input.kind){
  case 'some':if(!Object.hasOwn(input,'value'))throw new TypeError('missing value');return input.value===undefined?fallback:input.value;
  case 'none':return fallback;
  case 'error':if(!Object.hasOwn(input,'error'))throw new TypeError('missing error');throw input.error;
  default:throw new TypeError('unknown kind');
 }
}

